insert into public.hotspots (slug,name,meitei_name,tagline,description,history,category,district,location,lat,lng,images,photo_refs,best_time,best_seasons,entry_fee,timings,how_to_reach,distance_km,duration_hours,tips,accessibility,tags,featured,sort_weight,verification,sources) values ('liyai-khullen','Liyai Khullen','Liyai','The 500-year-old Poumai village where the Barak river begins','Liyai Khullen is the largest and oldest Poumai Naga village, reckoned at over 500 years old. The name is glossed locally as ''people of the sea''. The village keeps stone monoliths, old water pools and ancient banyan trees, and the Barak — one of the longest rivers in the region, which eventually reaches the Bay of Bengal — rises here. Caves and waterfalls in the surrounding hills are still being opened up to visitors, including the Vaonuhro valley and a giant Himalayan lily garden.',NULL,'heritage','Senapati','Liyai Khullen, Paomata sub-division, Senapati district',25.464830499999998,94.27071719999999,'[]'::jsonb,'[{"provider": "google-places", "ref": "places/ChIJgYxIcViESDcRrrPvO4TjPbg/photos/Aa-ngMZomt6Hs5QoCQ_h0T23mN5XYaP5Ph3gs9cgH97bhlxjzzJ_j6K0Iq1DbZ2WFdWB4lqftCRfnf7WC7Mk7QMj7lbcaNeN2w-WS9Rqn10B9ipo2otcySuxPelDhWPVwmDutNlkk1sj7C_fy7DioeA_SMDPiPL0nSbVIECSg-LcVyDhhtwKxSf_remPJqGO-ljXEAetKoNWKcfg7bElVBliU8JqOdVLJpTseOkRjKtBP9r5etonQroCmAi7UHAx-ZsNWwvfgIfwYcwWEnnCqha4G74fGon1mrocwVHED2U2UjkBEqgnpmp7fUt_wFNlDtgF2i4pqO__G1tMcwoHED9znT9BDQEUIiMjUcXDDDBaGjSxmLYbKgLEepGqHVZjavsHKBCMMrgbkJ1OGqPk3ISZPUI8BSAPzMsQc7496sudUrex0A", "width": 1280, "height": 606, "attribution": [{"name": "titus zhonah", "uri": "https://maps.google.com/maps/contrib/109077404152843206567"}]}, {"provider": "google-places", "ref": "places/ChIJgYxIcViESDcRrrPvO4TjPbg/photos/Aa-ngMYfNn1MFKIsINkr6fnLxLCa6T6MPM6pRMRR0Agv7XVkzYmkShn9ZCWJwue9AxJLFYT7McfsLQlispZ5o-PM4k_24Gce_2pdp-vpJ2FDz66r3ZpCOIwR53DKdoTpNHZiegJEN9m8X7QBUC7sL_7Lq5t-HOkWFL6Y_bN1yoChvMlImQ4oY7jmWPl67P7ZDSt5ZADTiXi7mQtjcCMghjymGMGyyV_IRHGibfnxE8XcBRZ_mb1M