insert into public.hotspots (slug,name,meitei_name,tagline,description,history,category,district,location,lat,lng,images,photo_refs,best_time,best_seasons,entry_fee,timings,how_to_reach,distance_km,duration_hours,tips,accessibility,tags,featured,sort_weight,verification,sources) values ('nillai-tea-estate','Nillai Tea Estate','Nilai Tea Estate','Manipur''s organic green-tea garden, hand-plucked and sun-dried','Nillai Tea Estate sits at Talui, the second-biggest town in Ukhrul district. It specialises in green tea; the leaf is hand-plucked and sun-dried rather than machine-processed. Visitors can walk the gardens, follow the production process, sit for a tasting and birdwatch along the edges.','Described in several sources as the first organic tea estate in Manipur — treat that claim as unverified.','park','Ukhrul','Talui, Ukhrul district',25.1783489,94.3444212,'[]'::jsonb,'[{"provider": "google-places", "ref": "places/ChIJNwNWTGv1SDcR5bIsw8kIB4k/photos/Aa-ngMYEsHMe-_bxks63SIqmjXHy90DY5Dv58OVDfgpsYEABe18eXtVfh0-m1zOPilmG41CXabJec6H0hOqLr7em5V_oHK1IzmkKDZLhAyyY0sj4UtwvydVuZEb4-dvAjpou7zrStPflO9fbl_02BFIlx9gENTnkzyH429iqIwDVhZBTeL9n0JTnxNVOT2ySWP0HTP2Pzr3-r3V0iLepkOrJC97EHkfK7UTG_q5cp2u6sbigy4vNZzFcSAFM0viTtLUvaQm9rjgVPwEyRtbFfyieIblpt0HEvV050a8phjqWuBplrka3Ip2Cy0Flb3aX27l_OZFmMvKmVXySvxjYzaVGY1KU_yaAoFYxE8jJCtwB3ZI5WU-TQXv8Pc7O5FUVO3KV-2IzgB0_D28vyxdpygSiFnJCaaBNsFXodYiIR9szep8", "width": 1616, "height": 1080, "attribution": [{"name": "ABONA ATHOKPAM", "uri": "https://maps.google.com/maps/contrib/100933927708960957885"}]}, {"provider": "google-places", "ref": "places/ChIJNwNWTGv1SDcR5bIsw8kIB4k/photos/Aa-ngMbgFlxhBiadU_7cv6fdp-Y0_SdLhogmmqkgYiHrbXHBfJVZJIT9xyFF6z0oTxBIBJEmLUQ7OatWRvCBykLkp4zlivwICytVYQZQJlM8Jy-rOkljskha5ebcamjpXi1YyKbcD2kKGEikeH2zzr8zEGOww4rfC8LmM15LVrbMG4Ws_SMY7BmL6QO_KitOCw_yQBs4-ZxDFWaSdPZ2MoxDVd38AuPFfJKSKvtuYJp5rIePoGGoJxGVUchPq6WeJrnyIFmMXAA7GA7haRWEGabDO1S8W6ylORs-kPyg5b791Vmz3LmzQ2Kng9MPESc4fjEPXXTGYjXLAWNQJ0ND4HqcwcGxLtV7SIxn3dKfrnI7Avz5XPwhx