insert into public.hotspots (slug,name,meitei_name,tagline,description,history,category,district,location,lat,lng,images,photo_refs,best_time,best_seasons,entry_fee,timings,how_to_reach,distance_km,duration_hours,tips,accessibility,tags,featured,sort_weight,verification,sources) values ('longpi-pottery-village','Longpi (Nungbi) Black Pottery Village','Nungbi','Pottery made from crushed serpentine stone, without a wheel','Longpi black pottery comes from two Tangkhul villages, Longpi Khullen and Longpi Kajui. The body is a paste of ground black serpentine rock and a brown clay found only here; potters shape every piece by hand, with no wheel at all, then polish, sun-dry and fire it in an open bonfire. The black comes from reduction firing and the sheen from rubbing the hot pot with a local tree leaf. The technique is traced back to the Neolithic. Visiting means going to the workshops in the village and watching the whole sequence.',NULL,'heritage','Ukhrul','Longpi Khullen and Longpi Kajui, Ukhrul district',24.6257496,93.36175519999999,'[]'::jsonb,'[{"provider": "google-places", "ref": "places/ChIJG2bb_B7pTjcRMH-nEBDTYAM/photos/Aa-ngMYOxVgNxk510PQu_zfuTtJENVn0sZWixL6MTpbkM0WlhPs4TD559wUAniApk1bZ2ZsRieZ0yRXpCXZkIcQeabD-0gxthkeuyPLYbvmbxoW0QMhkunjFU1b-dXN51OySuSpUqEJe0d74qhRENHmbRayq5OERwtvvCoFyIQZ8X-zLXAZwMRN8Lk2ZyUj__7a59vsJJ9ubFMMYRwOwslH3uk2kC3l-8fKXYJpdUzDHqsZa9exgZqjn9I0mKG1ceCCQuRCUqXFT8VMh5E_7FexuG9YM67SWxdZK8aO-bsLz7qdRyn1iAanyMLunJ9QriNhlbiXeyYvbTF-JJHRa_ePkQRBy-HtWIRbjTlfaVMWA1GUHVpCLRsmSpcP9PCjdxXh5jxN84kSwrof-VYKCEM9SpDKSB7y0Stq42w5d7oGqPSk", "width": 640, "height": 480, "attribution": [{"name": "Aleng Th Gangte", "uri": "https://maps.google.com/maps/contrib/115072938817251737927"}]}, {"provider": "google-places", "ref": "places/ChIJG2bb_B7pTjcRMH-nEBDTYAM/photos/Aa-ngMagJKnwWYulfBgCFMTVBLUXuzgv8KyShm29aah64xVvd2IQBMe17SPJ5XfoTkqn15vFGZdxPZAOaWcWx-30sOo4BU2GQiVnYCaOPtW-ltLmHKR093HohDyNgjxe9tyD_ggX3iZrbPA50oh7fDbwAk3V_2OAlaFRlAz6NWsg1HqWEv-s53Z03KBuax9W74SFjy