insert into public.hotspots (slug,name,meitei_name,tagline,description,history,category,district,location,lat,lng,images,photo_refs,best_time,best_seasons,entry_fee,timings,how_to_reach,distance_km,duration_hours,tips,accessibility,tags,featured,sort_weight,verification,sources) values ('takmu-water-sports-complex','Takmu Water Sports Complex',NULL,'Where the boating on Loktak is actually organised','The water sports complex at Takmu on Loktak, run as the organised boating and watersports point for the lake. It is the official counterpart to the informal boatmen at Thanga and Sendra.',NULL,'park','Bishnupur','Takmu, Loktak Lake, Bishnupur district',24.5088331,93.7851676,'[]'::jsonb,'[{"provider": "google-places", "ref": "places/ChIJL2oR1d81STcRIJ3SwUfbe8c/photos/Aa-ngMb47J3aBO15j6OtpLx6klXjLHBUkvmtRHn7oj5JZua1Mdf2S0bHwYrzUahworpi6pO1zbggSAtdFOHuu82fSgm1lHX3Qz0tY0CLDxeNwfEAHAZCi6FECttfiHXjRa97uPebTR5mC2qm_kFdSug8gACvHbFidBw_Ba8_cfkMwTOL64-RUAX6PkMZSYg358UApxCT5JP-x3JdFSDvZXs7pwwRT5qO2DOmsa3DcqYaiQ9ontZx1x8pyn24yu_A7So48jr_Po0pHnF9sZqDgum-aQvhH8Nnb4bl7-WlPsccaGyE1aaPMnv9hLhGN9v_nfWKCqNJhNHLR8Qmj4yoPzEuglo-ejHB6CZwEV7uW-cgbFYD-wbalziMD1mX2goDF1-R5at0Ybv7HF_-RfQVPP4plrI-FiMLyEiSPjgv5lHeIXEpCopC", "width": 1920, "height": 1080, "attribution": [{"name": "Achouba Maibam", "uri": "https://maps.google.com/maps/contrib/104739656686503371126"}]}]'::jsonb,NULL,'{"autumn","winter","spring"}',NULL,NULL,'On Loktak near Sendra, about 48 km from Imphal via Moirang.',0,2,'{"Confirm operating status before travelling — the complex has been through several operation-and-maintenance tender cycles."}','{"wheelchairAccessible": false, "notes": ""}'::jsonb,'{"activity","boating","watersports","loktak","bishnupur"}',false,100,'official','["https://manipurtourism.gov.in/in-around-loktak-lake/"]'::jsonb) on conflict (slug) do nothing;
insert into public.hotspots (slug,name,meitei_name,tagline,description,history,category,district,location,lat,lng,images,photo_refs,best_time,best_seasons,entry_fee,timings,how_to_reach,distance_km,duration_hours,tips,accessibility,tags,featured,sort_weight,verification,sources) values ('ithai-barrage','Ithai Barrage',NULL,'The dam that turned Loktak into a reservoir','The Ithai Barrage impounds the Manipur river just below the confluence of the Imphal and Khuga rivers. Built to regulate Loktak''s water level for the hydroelectric project, it effectively converted the lake into a reservoir — and is the single most contested piece of infrastructure in Manipur''s environmental politics, blamed for the loss of migratory fish and the degradation of the phumdis. For a visitor interested in why Loktak looks the way it does, this is the explanation.',NULL,'memorial','Bishnupur','Ithai, Bishnupur district',24.4229576,93.8400255,'[]'::jsonb,'[{"provider": "google-places", "ref": "places/ChIJUwkRqHZJSTcRiG8Xz9kfO1o/photos/Aa-ngMYPg7NqW5j0o4_MNOrTCDdEcb7_vM1fVF44jGvxcq31kO2kw1S944bMmurWSv3qty7dR1zJ8o06uwJqPRSNRRjvfpbuEghl__MjwtlGLrNKLQqEiQq5UMX5JmqZns1pOnS8t2--_ZvTgIJXiMYaDAIz6I2qTsdREkE6kgmk9vVPKfjvaZ7Uky3FRP-cGaGdiVnM0NYjp2RMD7SzMsyYeESP77OCVobBhnG4HBkT9k0HyvBOpA0ylIII16ehj_i_jZryrHL6olGIWv2vmdsekzmSHYYCbRTL5yJ1vVtMjhSUJPlk8PthIs2aDrTI6VjAv8ImwXnYnFQrYjqeRQ2agPvAs0C2Tn8IRYHSdGR4nXTs3Dy7VX6b0TAfnG5hI3wXfG4BFb_TMaVZBTtt5QnGTOHfUlLqSqY", "width": 1620, "height": 1080, "attribution": [{"name": "Warepam Deven , phubala", "uri": "https://maps.google.com/maps/contrib/113553192515132074879"}]}, {"provider": "google-places", "ref": "places/ChIJUwkRqHZJSTcRiG8Xz9kfO1o/photos/Aa-ngMa2RDTBKiR8XryaiN7agETe7TGAl-Q4Aptq21MGyAzYIIV68UByA8jwLGDwyXaS8TYeeVc2IPYJX1a3goWCqmZvhD4WPV5TDy0z7NGvETbabIBzDNjWhfEyE0hVZRtNi9MCEzheLL3NU-FA10bxTXe4XCZhxbNVSBnlnSOjbiad06Rr0gzZgm40Qsdtp6KGWJL3MrU2ZzgOzR2RfT-MnYvHdJJNKMVRDF8qszFNpi92ugssPTmwWo5dOAaod8dgHKqTFXBKAR2gW76Y_kmpBQ9n8pnQNM0r1e-SvFnm6-JdysMfh5foqCU