insert into public.hotspots (slug,name,meitei_name,tagline,description,history,category,district,location,lat,lng,images,photo_refs,best_time,best_seasons,entry_fee,timings,how_to_reach,distance_km,duration_hours,tips,accessibility,tags,featured,sort_weight,verification,sources) values ('kachouphung-lake','Kachouphung Lake','Azoa Jenephiu Magi Lake (adjacent)','A hill lake in Kamjong with a second, smaller lake beside it','Kachouphung is a lake in the Ukhrul–Kamjong belt, listed by Manipur Tourism together with the nearby Azoa Jenephiu Magi lake and a cold water fishery project. It is one of the eastern hills'' quietest water bodies.','Already present in the existing hotspot seed as ''kachouphung-lake'' — merge rather than duplicate. Added here only for the Azoa Jenephiu Magi lake and cold-water fishery detail.','lake','Kamjong','Kachouphung, Ukhrul/Kamjong district',25.072469599999998,94.72692420000001,'[]'::jsonb,'[{"provider": "google-places", "ref": "places/ChIJr15JXgdHSDcRLNEJhczmjVc/photos/Aa-ngMY8QGrnrXQ0EeKal3k6Zs-_mIg-Be6k1Myf7a4ASmMmSAHhJd7N8ycNyo28s0031a98AU1zvtL0e0C-zX3yUKUhfV7y4UiUqj3ekYyhnUniLz6WT8uS12r0uKErsZSWHzUkobUGmnSXJ-iCUAYroWMvfWoHGcWS39kkpUC8bSOdweAhqtTs_6LlCZAJZZobkNFCsLQiHIkdgaztTyyLXkBuLIvUPWylcckVmBBlQsIKrIAqHD7NDQeuog9F-vd0vq4xeiAVI5vD6IbfvhdNIaZW_OG3etGCj--geX8uJ3NAQHtKD3b_k7VczRmkJ7DgII71VGN8Y3C20d-wCr6Znp2JkBTOws02AfuKya5DHODbcXiyX-BQFE-rGguNUWLl8qKbPiJmMUh4uh6g7-3ZsclGcWQ", "width": 3472, "height": 4624, "attribution": [{"name": "Angam vashi", "uri": "https://maps.google.com/maps/contrib/106621881588614220392"}]}, {"provider": "google-places", "ref": "places/ChIJr15JXgdHSDcRLNEJhczmjVc/photos/Aa-ngMbwYRhsya5KXHPVxvzeHgWHqDuFP3Sg8aSejus-B4L32_uFhxW1YvxtIvoIz4qSMxreU1rhA56VDYq419OW-kQgL7bTYYtiOHBen8N69aCpE16DM3sukARPPhPn48nzcTJkbpml2gcXMZxs-FyOrx0xz0IOrUxuyyhduJWpWnVMMF_2VUQg_NmRYsExOzbwlh_eRwO_oe4GdTAHQc_zxNkqcv-9BEWYLs9SSUPBaK_ydw28hdGFkNx3aWvNoEa31N7Y4COUqwflUXFz061QyWVw8Z55HipD7GRXf4FVJRmyb3ytUL_HGSe8nZ5bW27vUOj5zMPLK5fKvP9QP4RYuY66